// ═══ CONFIGURAÇÃO ÚNICA ═══════════════════════════════════════════════════
// Todo id vive aqui. Id espalhado pelo fluxo é o que faz ninguém ter coragem
// de mexer depois — e é o que transforma "adicionar uma unidade" em caçada.

const cfg = {
  // ── Destino ──────────────────────────────────────────────────────────────
  graphVersion: $env.META_GRAPH_VERSION || 'v21.0',
  token:        $env.META_CAPI_TOKEN || '',

  // Código do Gerenciador de Eventos. Com ele preenchido o evento aparece em
  // "Eventos de teste" e NÃO entra na otimização. Comece com ele, apague depois.
  testEventCode: $env.META_CAPI_TEST_CODE || '',

  // Roda o fluxo inteiro e grava no log SEM chamar a Meta. Serve para conferir
  // o casamento de telefone e o mapa de etapas antes de valer para a campanha.
  modoTeste: String($env.META_CAPI_DRY_RUN || 'false').toLowerCase() === 'true',

  // ── Unidades ─────────────────────────────────────────────────────────────
  // Chave = pipeline_id do funil. É o filtro que protege o pixel: conversão de
  // outra unidade caindo no pixel de Imperatriz contamina a otimização das
  // campanhas dela, e o estrago é silencioso — ninguém vê, a campanha só piora.
  unidades: {
    '14091100': {
      nome: 'imperatriz',
      pixel: '1076495867156119',
      wabaId: '1558318502323307',
      phoneNumberId: '1192220830640227',
    },
  },

  // ── Mapa de etapas → evento (Imperatriz) ─────────────────────────────────
  etapas: {
    '108773008': 'AddToCart',          // AGENDADO
    '108773012': 'InitiateCheckout',   // COMPARECEU
    '142':       'Purchase',           // GANHO / CONCLUÍDO
  },

  // ── Lead quente ──────────────────────────────────────────────────────────
  // Não é mudança de etapa: é o campo de qualificação. O webhook de lead
  // atualizado não traz custom_fields de forma confiável, então o fluxo relê o
  // lead na API e procura por este field_id.
  qualificacao: {
    fieldId: Number($env.KOMMO_CF_QUALIFICACAO || 2440809),
    // "Quente" = 1832805. Numérico também aceito, via valorMinimo.
    enumQuente: Number($env.KOMMO_ENUM_QUENTE || 1832805),
    valorMinimo: Number($env.KOMMO_QUALIF_MINIMO || 0),
  },

  kommoSubdomain: $env.KOMMO_SUBDOMAIN || 'attivacorpoementeitz',

  janelaDias: Number($env.META_CAPI_JANELA_DIAS || 7),
};

// Nome do evento por gatilho. LeadSubmitted é o que alimenta a otimização —
// por isso ele tem alerta de falha próprio mais adiante no fluxo.
const EVENTOS = {
  mensagem:           'ViewContent',
  lead_quente:        'LeadSubmitted',
  agendamento:        'AddToCart',
  consulta_realizada: 'InitiateCheckout',
  compra:             'Purchase',
};

return [{ json: { cfg, EVENTOS } }];

// O ViewContent não passa pelo Kommo, então não tem pipeline_id. A unidade
// vem do phone_number_id, que é o número que recebeu a mensagem.
const { cfg, EVENTOS } = $('Config').first().json;
const porNumero = Object.entries(cfg.unidades).reduce((m,[pid,u]) => (m[u.phoneNumberId]=pid, m), {});
return $input.all().map(i => ({ json: {
  event_name: EVENTOS.mensagem,
  event_id: 'view-' + i.json.ctwa_clid,
  event_time: Number(i.json.event_time),
  ctwa_clid: i.json.ctwa_clid,
  telefone: i.json.telefone,
  wamid: i.json.wamid,
  kommo_lead_id: null, valor: null,
  pipeline_id: porNumero[String(i.json.phone_number_id)] || null,
}}));

// O webhook de lead atualizado não traz custom_fields de forma confiável,
// por isso relemos o lead. Dispara UMA vez: a reserva do event_id
// 'quente-<lead>' impede o reenvio se alguém tirar e recolocar a estrela.
const { cfg, EVENTOS } = $('Config').first().json;
const out=[];
for (const i of $input.all()) {
  const l=i.json; const cfs=l.custom_fields_values||[];
  const campo=cfs.find(c=>Number(c.field_id)===cfg.qualificacao.fieldId);
  if(!campo) continue;
  const v=campo.values?.[0]||{};
  const quente = Number(v.enum_id)===cfg.qualificacao.enumQuente
    || (cfg.qualificacao.valorMinimo>0 && Number(v.value)>=cfg.qualificacao.valorMinimo);
  if(!quente) continue;
  out.push({json:{ event_name:EVENTOS.lead_quente, event_id:'quente-'+l.id,
    event_time:Math.floor(Date.now()/1000), kommo_lead_id:String(l.id),
    pipeline_id:String(l.pipeline_id), telefone:null, valor:null }});
}
return out;

// Etapa sem evento no mapa não vira nada. Inventar um evento porque a etapa
// 'parece' de venda é o caminho para o pixel aprender errado.
const { cfg, EVENTOS } = $('Config').first().json;
const out=[];
for (const i of $input.all()) {
  const l=i.json; const nome=cfg.etapas[String(l.status_id)];
  if(!nome) continue;
  out.push({json:{ event_name:nome, event_id:'kommo-'+l.id+'-'+nome,
    event_time:Math.floor(Date.now()/1000), kommo_lead_id:String(l.id),
    pipeline_id:String(l.pipeline_id), telefone:null,
    valor: nome===EVENTOS.compra ? (l.price||0) : null }});
}
return out;

// ═══ CASAMENTO DE TELEFONE ════════════════════════════════════════════════
// A maior fonte de perda de atribuição nesse tipo de integração, e não é
// exagero: o WhatsApp entrega "5599981991934" e a recepção digitou
// "(99) 8199-1934". Comparar as duas strings acerta quase nada.
//
// A regra é comparar só dígitos e gerar as variantes brasileiras: com e sem o
// DDI 55, com e sem o nono dígito. Os 8 últimos são o que sobra sempre, mas
// sozinhos casam pessoas diferentes de DDDs diferentes — por isso as variantes
// vêm antes, e o sufixo de 8 é o último recurso.

function variantes(bruto) {
  const d = String(bruto || '').replace(/\D/g, '');
  if (d.length < 8) return [];

  const v = new Set([d]);
  const semDdi = d.startsWith('55') ? d.slice(2) : d;
  v.add(semDdi);
  v.add('55' + semDdi);

  // Nono dígito: entra e sai conforme a época do cadastro.
  if (semDdi.length === 11 && semDdi[2] === '9') {
    const sem9 = semDdi.slice(0, 2) + semDdi.slice(3);
    v.add(sem9); v.add('55' + sem9);
  }
  if (semDdi.length === 10) {
    const com9 = semDdi.slice(0, 2) + '9' + semDdi.slice(2);
    v.add(com9); v.add('55' + com9);
  }
  return [...v];
}

return $input.all().map((item) => {
  const t = item.json.telefone || item.json.phone || '';
  return { json: { ...item.json, variantes: variantes(t), sufixo8: String(t).replace(/\D/g,'').slice(-8) } };
});

// ═══ MONTA O EVENTO E DECIDE SE ELE SAI ═══════════════════════════════════
// Ponto único de montagem: os três gatilhos convergem aqui. Triplicar esta
// lógica seria garantir que as três cópias divergissem na primeira correção.
//
// Três campos precisam andar juntos para a Meta casar o evento com o anúncio:
// action_source 'business_messaging', messaging_channel 'whatsapp' e o
// ctwa_clid dentro de user_data. Faltando um, o evento entra e não atribui —
// e o sintoma é o pior possível: aparece "recebido" no Gerenciador, com zero
// atribuição, o que parece funcionamento.

const { cfg, EVENTOS } = $('Config').first().json;
const agora = Math.floor(Date.now() / 1000);
const saida = [];
const descartes = [];

for (const item of $input.all()) {
  const d = item.json;
  const unidade = cfg.unidades[String(d.pipeline_id)] || null;

  // Filtro de unidade primeiro, antes de qualquer processamento.
  if (!unidade) {
    descartes.push({ motivo: 'unidade_fora_do_mapa', event_name: d.event_name,
      kommo_lead_id: d.kommo_lead_id, pipeline_id: String(d.pipeline_id || ''), detalhe: d });
    continue;
  }

  // Sem clique não há o que atribuir. Não é erro — é lead de outra origem.
  if (!d.ctwa_clid) {
    descartes.push({ motivo: 'sem_ctwa_clid', event_name: d.event_name,
      kommo_lead_id: d.kommo_lead_id, telefone: d.telefone, detalhe: d });
    continue;
  }

  const quando = d.event_time || agora;
  if (agora - quando > cfg.janelaDias * 86400) {
    descartes.push({ motivo: 'fora_da_janela_7d', event_name: d.event_name,
      kommo_lead_id: d.kommo_lead_id, detalhe: { quando, agora } });
    continue;
  }

  const evento = {
    event_name: d.event_name,
    event_time: quando,
    action_source: 'business_messaging',
    messaging_channel: 'whatsapp',
    event_id: d.event_id,
    user_data: {
      ctwa_clid: d.ctwa_clid,
      whatsapp_business_account_id: unidade.wabaId,
    },
  };
  // Valor só em Purchase, e só quando existe. Mandar 0 ensina a Meta que a
  // venda vale zero.
  if (d.event_name === EVENTOS.compra && Number(d.valor) > 0) {
    evento.custom_data = { currency: 'BRL', value: Number(d.valor) };
  }

  saida.push({ json: {
    ...d,
    unidade: unidade.nome,
    pixel: unidade.pixel,
    corpo: { data: [evento], ...(cfg.testEventCode ? { test_event_code: cfg.testEventCode } : {}) },
  }});
}

// O nó Code do n8n tem UMA saída só — devolver [aprovados, descartados] faz ele
// ler uma lista de listas e recusar tudo. Sai uma lista única, marcada com
// _aprovado, e o IF seguinte separa os dois caminhos.
return [
  ...saida.map((x) => ({ json: { ...x.json, _aprovado: true } })),
  ...descartes.map((x) => ({ json: { ...x, _aprovado: false } })),
];

// O Config é um nó Code e, como todo Code, TROCA o item — depois dele o corpo do
// webhook não existe mais. Por isso lemos direto do nó de webhook, pelo nome.
//
// A Kommo manda form-urlencoded em notação de colchetes, então as chaves chegam
// cruas: "leads[status][0][id]". Não existe $json.body.leads.status[0].id.
const origem = $('Kommo — lead atualizado').first().json;
const corpo = origem.body || origem.query || origem;

function achaId(o) {
  for (const [k, v] of Object.entries(o || {})) {
    if (/^leads\[(status|update|add)\]\[\d+\]\[id\]$/.test(k)) return String(v);
  }
  // Alguns proxies já entregam aninhado; aceita os dois formatos.
  const l = o?.leads || {};
  for (const tipo of ['status', 'update', 'add']) {
    const id = l?.[tipo]?.[0]?.id;
    if (id) return String(id);
  }
  return null;
}

const leadId = achaId(corpo);
if (!leadId) return [];          // webhook sem lead: encerra sem erro
return [{ json: { leadId } }];

// O Config é um nó Code e, como todo Code, TROCA o item — depois dele o corpo do
// webhook não existe mais. Por isso lemos direto do nó de webhook, pelo nome.
//
// A Kommo manda form-urlencoded em notação de colchetes, então as chaves chegam
// cruas: "leads[status][0][id]". Não existe $json.body.leads.status[0].id.
const origem = $('Kommo — etapa alterada').first().json;
const corpo = origem.body || origem.query || origem;

function achaId(o) {
  for (const [k, v] of Object.entries(o || {})) {
    if (/^leads\[(status|update|add)\]\[\d+\]\[id\]$/.test(k)) return String(v);
  }
  // Alguns proxies já entregam aninhado; aceita os dois formatos.
  const l = o?.leads || {};
  for (const tipo of ['status', 'update', 'add']) {
    const id = l?.[tipo]?.[0]?.id;
    if (id) return String(id);
  }
  return null;
}

const leadId = achaId(corpo);
if (!leadId) return [];          // webhook sem lead: encerra sem erro
return [{ json: { leadId } }];

// O nó Postgres anterior devolveu só o clique. O evento que veio do funil ficou
// para trás, porque nó de banco troca o item. Aqui os dois voltam a ser um.
//
// Este nó existe por causa de um comportamento do n8n que já quebrou o fluxo
// quatro vezes hoje: todo nó Code ou Postgres SUBSTITUI o item. Quem precisa do
// que veio antes tem que buscar pelo nome do nó, com item pareado.
const evento = $('Variantes do telefone').all();
const saida = [];

$input.all().forEach((item, i) => {
  const clique = item.json || {};
  const base = (evento[i] || evento[0] || {}).json || {};
  if (!clique.ctwa_clid) {
    // Sem clique casado: segue adiante marcado, para virar linha de descarte
    // com o motivo em vez de sumir.
    saida.push({ json: { ...base, ctwa_clid: null } });
    return;
  }
  saida.push({ json: { ...base, ctwa_clid: clique.ctwa_clid, telefone: clique.telefone || base.telefone } });
});
return saida;
